     "summary": "商务部27日举行例行新闻发布会，商务部新闻发言人黄玲在回应有关美国政府考虑对自中国进口商品额外加征7.5%关税的提问时说，美方以“产能过剩”为由对包括中国在内的16个经济体发起301调查，将经贸问题政治化，是典型的单边主义、保护主义行为，中方对此坚决反对。我们将继续密切关注并全面评估美方后续举措，并保留采取一切必要措施的权利。（文章来源：新华社）",
